from itertools import product

def solve(n):
    solutions = []
    # a_i are in {0, ..., n} and sum(a_i) = n+1
    # We can generate all such sequences
    def get_sequences(n, target):
        if n == 0:
            yield ()
            return
        for i in range(target + 1):
            for rest in get_sequences(n - 1, target - i):
                yield (i,) + rest

    for a in get_sequences(n, n + 1):
        # b_k = count of a_i = k
        b = [0] * (n + 1)
        for val in a:
            if val <= n:
                b[val] += 1
            else:
                # If any a_i > n, it's not a good sequence
                # because the roots of the first product are a_i
                # and they must be in {0, ..., n}.
                # Actually, the problem says a_i is any integer.
                # But the RHS roots are {0, ..., n}.
                # So a_i must be in {0, ..., n}.
                pass

        # Check if all a_i are in {0, ..., n}
        if any(x > n for x in a):
            continue

        # b_k = count of a_i = k
        # Actually, I already did that.
        # Let's re-calculate b.
        b = [0] * (n + 1)
        for val in a:
            b[val] += 1

        # Now check if a_k = count of b_i = k
        # Wait, b is a sequence of length n+1.
        # So a_k = count of b_i = k for k = 0, ..., n.
        # But b_i could be > n?
        # b_i is count of a_j = i. Since there are n+1 such a_j,
        # b_i is at most n+1.
        # If some b_i > n, then the second equation
        # product_{k=0}^n (x - b_k) = product_{k=0}^n (x - k)^{a_k}
        # would have a root b_i > n.
        # But the RHS roots are only in {0, ..., n}.
        # So b_i must be in {0, ..., n}.

        valid_b = True
        for val in b:
            if val > n:
                valid_b = False
                break
        if not valid_b:
            continue

        # Now calculate the new a from b
        a_new = [0] * (n + 1)
        for val in b:
            a_new[val] += 1

        if a == tuple(a_new):
            solutions.append(a)

    return solutions

