def find_good_sequences(n):
    good_sequences = []
    # a_0 + a_1 + ... + a_n = n+1
    # a_1 + 2*a_2 + ... + n*a_n = n+1
    # a_k is the count of k in the sequence b_0, ..., b_n
    # b_k is the count of k in the sequence a_0, ..., a_n
    # Also a_i, b_i are in {0, ..., n}

    # We can iterate over all possible sequences a = (a_0, ..., a_n)
    # such that a_i \in {0, ..., n} and \sum a_i = n+1
    # and \sum k*a_k = n+1.
    # Then we check if the sequence b defined by the counts of a_i
    # also satisfies the conditions.

    import itertools

    # Using a more efficient way to generate sequences
    # The sum of a_i is n+1, and a_i is in {0, ..., n}.
    # This is equivalent to finding non-negative integers a_0, ..., a_n
    # such that \sum a_i = n+1 and \sum i*a_i = n+1.

    for a in itertools.product(range(n+1), repeat=n+1):
        if sum(a) == n+1 and sum(i * a[i] for i in range(n+1)) == n+1:
            # b_k is the count of k in sequence a
            b = [0] * (n+1)
            for val in a:
                if val <= n:
                    b[val] += 1
                else:
                    # This case shouldn't happen since a_i \in {0, ..., n}
                    pass

            # Now check if b is a good sequence too
            if sum(b) == n+1 and sum(i * b[i] for i in range(n+1)) == n+1:
                # Now check if the counts of b are a
                a_check = [0] * (n+1)
                for val in b:
                    if val <= n:
                        a_check[val] += 1
                    else:
                        pass

                if a_check == list(a):
                    good_sequences.append(a)

    results = []
    for a in good_sequences:
        res = sum((i+1) * (a[i]**2) for i in range(n+1))
        results.append(res)
    return sorted(list(set(results)))

