import itertools

def find_good_sequences(n):
    # sum(a_i) = n+1, a_i in {0, ..., n}
    # Generate all such sequences a.
    # This is a stars and bars problem.
    # But we can just use a recursive generator to find all non-negative a_i summing to n+1.

    def generate_sequences(target, length):
        if length == 1:
            yield (target,)
            return
        for i in range(target + 1):
            for rest in generate_sequences(target - i, length - 1):
                yield (i,) + rest

    good_sequences = []
    for a in generate_sequences(n + 1, n + 1):
        # b_k = count of k in a
        b = [0] * (n + 1)
        for val in a:
            if val <= n:
                b[val] += 1

        # a_k = count of k in b
        a_prime = [0] * (n + 1)
        for val in b:
            if val <= n:
                a_prime[val] += 1

        if list(a_prime) == list(a):
            good_sequences.append(a)
    return good_sequences

