                if sum(b) == n + 1 and sum(k * b[k] for k in range(n + 1)) == n + 1:
                    a_new = [0] * (n + 1)
                    for val in b:
                        if val <= n:
                            a_new[val] += 1

                    if current_a == tuple(a_new):
                        results.append(current_a)
            return

        rem_count = n + 1 - idx
        rem_sum = n + 1 - current_sum
        rem_weighted_sum = n + 1 - current_weighted_sum

        if rem_sum < 0 or rem_sum > rem_count * n:
            return

        # Max weighted sum: put as much as possible into the largest indices.
        max_w = 0
        temp_sum = rem_sum
        for j in range(n, idx - 1, -1):
            take = min(temp_sum, n)
            max_w += j * take
            temp_sum -= take
        if temp_sum > 0: return # Should be handled by rem_sum > rem_count * n
        if rem_weighted_sum > max_w:
            return

        # Min weighted sum: put as much as possible into the smallest indices.
        min_w = 0
        temp_sum = rem_sum
        for j in range(idx, n + 1):
            take = min(temp_sum, n)
            min_w += j * take
            temp_sum -= take
            if temp_sum == 0:
                break
        if temp_sum > 0: return
        if rem_weighted_sum < min_w:
            return

        for val in range(min(rem_sum, n) + 1):
            backtrack(idx + 1, current_a + (val,), current_sum + val, current_weighted_sum + idx * val)

    backtrack(0, (), 0, 0)
    return results

