def find_good_sequences_v4(n):
    results = []
    def generate_partitions(remaining, max_val, current_partition):
        if remaining == 0:
            # The partition is {p_1, ..., p_m} where each p_i > 0.
            # The number of parts is m.
            # The number of zero parts is (n+1-m).
            # So the multiset of parts is {p_1, ..., p_m, 0, 0, ..., 0} with (n+1-m) zeros.
            # Let a_k be the count of k in this multiset.
            a = [0] * (n + 1)
            for p in current_partition:
                a[p] += 1
            a[0] = (n + 1) - len(current_partition)

            # Check if sum a_i = n+1 and sum i a_i = n+1
            # They are always true by construction.

            # Now check f(f(a)) = a.
            # b_k = count of k in a.
            # a_k' = count of k in b.
            b = [0] * (n + 1)
            for x in a:
                if x <= n:
                    b[x] += 1
            a_prime = [0] * (n + 1)
            for x in b:
                if x <= n:
                    a_prime[x] += 1

            if a_prime == a:
                results.append(tuple(a))
            return

        for i in range(1, min(remaining, max_val) + 1):
            current_partition.append(i)
            generate_partitions(remaining - i, i, current_partition)
            current_partition.pop()

    generate_partitions(n + 1, n, [])
    return results

